class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        vector<vector<bool>> pac(m, vector<bool>(n, false));
        vector<vector<bool>> atl(m, vector<bool>(n, false));
        queue<pair<int,int>> qp, qa;
        auto insert = [&](int r, int c, vector<vector<bool>>& seen,
                          queue<pair<int,int>>& q) {
            if (!seen[r][c]) {
                seen[r][c] = true;
                q.push({r, c});
            }
        };
        for (int r = 0; r < m; ++r) {
            insert(r, 0, pac, qp);
            insert(r, n - 1, atl, qa);
        }
        for (int c = 0; c < n; ++c) {
            insert(0, c, pac, qp);
            insert(m - 1, c, atl, qa);
        }
        auto bfs = [&](queue<pair<int,int>>& q, vector<vector<bool>>& seen) {
            int dr[4] = {1, -1, 0, 0};
            int dc[4] = {0, 0, 1, -1};
            while (!q.empty()) {
                auto current = q.front();
                q.pop();
                int r = current.first, c = current.second;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                    if (!seen[nr][nc] && heights[nr][nc] >= heights[r][c]) {
                        seen[nr][nc] = true;
                        q.push({nr, nc});
                    }
                }
            }
        };
        bfs(qp, pac);
        bfs(qa, atl);
        vector<vector<int>> result;
        for (int r = 0; r < m; ++r)
            for (int c = 0; c < n; ++c)
                if (pac[r][c] && atl[r][c]) result.push_back({r, c});
        return result;
    }
};
